def merge_intervals(intervals):
    if not intervals:
        return []

    # copy to avoid mutating input
    sorted_intervals = sorted(( [s, e] for s, e in intervals ), key=lambda x: (x[0], x[1]))

    merged = []
    cur_start, cur_end = sorted_intervals[0]

    for s, e in sorted_intervals[1:]:
        if s <= cur_end:  # overlap or touching
            if e > cur_end:
                cur_end = e
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e

    merged.append([cur_start, cur_end])
    return merged

def toposort(nodes, edges):
    from heapq import heappush, heappop

    nodes_set = set(nodes)
    indeg = {n: 0 for n in nodes}
    adj = {n: set() for n in nodes}
    seen = set()

    for src, dst in edges:
        if src not in nodes_set or dst not in nodes_set:
            continue
        if src == dst:
            raise ValueError("cycle detected")
        if (src, dst) in seen:
            continue
        seen.add((src, dst))
        if dst not in adj[src]:
            adj[src].add(dst)
            indeg[dst] += 1

    heap = []
    for n in nodes:
        if indeg[n] == 0:
            heappush(heap, n)

    result = []
    indeg_copy = indeg.copy()
    while heap:
        n = heappop(heap)
        result.append(n)
        for nb in adj[n]:
            indeg_copy[nb] -= 1
            if indeg_copy[nb] == 0:
                heappush(heap, nb)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, w in items:
        if current_sum + w <= limit:
            current.append(name)
            current_sum += w
        else:
            batches.append(current)
            current = [name]
            current_sum = w
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    key_pat = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid line: {raw_line!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key_pat.match(key):
            raise ValueError(f"Invalid key: {key!r}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    data = b''.join(chunks)
    text = data.decode('utf-8')
    events = []
    current = []

    for line in text.splitlines():
        if line == '':
            if current:
                event_data = '\n'.join(current)
                if event_data == '[DONE]':
                    return events
                events.append(event_data)
                current = []
            continue

        if line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            current.append(val)
        # other fields and comments are ignored

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be non-negative")
    if not isinstance(attempt, int) or isinstance(attempt, bool):
        raise ValueError("attempt must be a non-negative integer")

    if base == 0 or cap == 0:
        return 0.0

    # if base already exceeds cap, the result is capped
    if base >= cap:
        return float(cap)

    # avoid building 2**attempt for huge attempt
    # base * 2**attempt > cap  <=>  attempt > log2(cap/base)
    try:
        limit = math.log2(cap) - math.log2(base)
    except ValueError:
        limit = float('inf')

    if attempt > limit:
        return float(cap)

    # attempt is small enough that the exact value fits in float
    return float(base * (2 ** attempt))
